import 'package:webview_flutter/webview_flutter.dart';
import 'package:webview_flutter_platform_interface/webview_flutter_platform_interface.dart';

import 'package:fa/ui/screens/chatgpt_oauth_webview.dart';

const _authorizeUrl =
    'https://auth.openai.com/oauth/authorize'
    '?response_type=code&client_id=app_EMoamEEZ73f0CkXaXp7hrann'
    '&redirect_uri=http%3A%2F%2Flocalhost%3A1455%2Fauth%2Fcallback'
    '&code_challenge=abc&state=st-1';
const _expectedState = 'st-1';

/// Captures every event the page's [NavigationDelegate] registers with the
/// platform, so tests can fire them like the native WebView would.
final class _CapturedDelegateEvents {
  NavigationRequestCallback? onNavigationRequest;
  PageEventCallback? onPageStarted;
  PageEventCallback? onPageFinished;
  WebResourceErrorCallback? onWebResourceError;
}

/// Minimal fake webview platform (same pattern as the CodeMie page tests):
/// a real [WebViewController] builds against it, and the delegate events
/// the page registers are captured for tests to fire on demand.
final class _FakeWebViewPlatform extends WebViewPlatform {
  final _FakePlatformWebViewController controller =
      _FakePlatformWebViewController();
  final _CapturedDelegateEvents events = _CapturedDelegateEvents();

  @override
  PlatformWebViewController createPlatformWebViewController(
    PlatformWebViewControllerCreationParams params,
  ) => controller;

  @override
  PlatformNavigationDelegate createPlatformNavigationDelegate(
    PlatformNavigationDelegateCreationParams params,
  ) => _FakePlatformNavigationDelegate(events);

  @override
  PlatformWebViewWidget createPlatformWebViewWidget(
    PlatformWebViewWidgetCreationParams params,
  ) => _FakePlatformWebViewWidget(params);
}

final class _FakePlatformWebViewController extends PlatformWebViewController {
  _FakePlatformWebViewController()
    : super.implementation(const PlatformWebViewControllerCreationParams());

  JavaScriptMode? javaScriptMode;
  Uri? loadedUri;
  String bodyText = '';

  @override
  Future<void> setJavaScriptMode(JavaScriptMode mode) async {
    javaScriptMode = mode;
  }

  @override
  Future<void> setPlatformNavigationDelegate(
    PlatformNavigationDelegate handler,
  ) async {}

  @override
  Future<void> loadRequest(LoadRequestParams params) async {
    loadedUri = params.uri;
  }

  @override
  Future<Object> runJavaScriptReturningResult(String javaScript) async =>
      bodyText;
}

final class _FakePlatformNavigationDelegate extends PlatformNavigationDelegate {
  _FakePlatformNavigationDelegate(this.events)
    : super.implementation(const PlatformNavigationDelegateCreationParams());

  final _CapturedDelegateEvents events;

  @override
  Future<void> setOnNavigationRequest(
    NavigationRequestCallback callback,
  ) async {
    events.onNavigationRequest = callback;
  }

  @override
  Future<void> setOnPageStarted(PageEventCallback callback) async {
    events.onPageStarted = callback;
  }

  @override
  Future<void> setOnPageFinished(PageEventCallback callback) async {
    events.onPageFinished = callback;
  }

  @override
  Future<void> setOnWebResourceError(WebResourceErrorCallback callback) async {
    events.onWebResourceError = callback;
  }
}

final class _FakePlatformWebViewWidget extends PlatformWebViewWidget {
  _FakePlatformWebViewWidget(super.params) : super.implementation();

  @override
  Widget build(BuildContext context) =>
      const SizedBox(key: Key('fake-webview'));
}

/// Records the page's route at push time so tests can await its
/// [Route.popped] future — the value the page pops with (the code on
/// success, null on cancel/timeout).
final class _PopRecorder extends NavigatorObserver {
  Route<dynamic>? route;

  @override
  void didPush(Route<dynamic> route, Route<dynamic>? previousRoute) {
    this.route = route;
  }
}

void main() {
  late _FakeWebViewPlatform platform;

  setUp(() {
    platform = _FakeWebViewPlatform();
    WebViewPlatform.instance = platform;
  });

  Future<_PopRecorder> pumpPage(
    WidgetTester tester, {
    Duration timeout = const Duration(minutes: 5),
  }) async {
    final recorder = _PopRecorder();
    await tester.pumpWidget(
      MaterialApp(
        home: Navigator(
          observers: [recorder],
          onGenerateRoute: (settings) => MaterialPageRoute(
            settings: settings,
            builder: (_) => ChatGptOAuthWebViewPage(
              authorizeUrl: _authorizeUrl,
              expectedState: _expectedState,
              timeout: timeout,
            ),
          ),
        ),
      ),
    );
    await tester.pump();
    return recorder;
  }

  group('chatGptNavigationDecision (issue #773 AC1)', () {
    test('a localhost callback with code + matching state is intercepted', () {
      String? code;
      String? error;
      final decision = chatGptNavigationDecision(
        'http://localhost:1455/auth/callback?code=c-1&state=$_expectedState',
        expectedState: _expectedState,
        onCode: (c) => code = c,
        onError: (e) => error = e,
      );

      expect(decision, NavigationDecision.prevent);
      expect(code, 'c-1');
      expect(error, isNull);
    });

    test('the 127.0.0.1 loopback form is intercepted too', () {
      String? code;
      final decision = chatGptNavigationDecision(
        'http://127.0.0.1:1455/auth/callback?code=c-2&state=$_expectedState',
        expectedState: _expectedState,
        onCode: (c) => code = c,
      );

      expect(decision, NavigationDecision.prevent);
      expect(code, 'c-2');
    });

    test('a state mismatch names the error and never navigates', () {
      String? code;
      String? error;
      final decision = chatGptNavigationDecision(
        'http://localhost:1455/auth/callback?code=c-3&state=other-session',
        expectedState: _expectedState,
        onCode: (c) => code = c,
        onError: (e) => error = e,
      );

      expect(decision, NavigationDecision.prevent);
      expect(code, isNull);
      expect(error, contains('state mismatch'));
    });

    test('an OAuth error param names the error and its description', () {
      String? code;
      String? error;
      final decision = chatGptNavigationDecision(
        'http://localhost:1455/auth/callback'
        '?error=access_denied&error_description=User+denied',
        expectedState: _expectedState,
        onCode: (c) => code = c,
        onError: (e) => error = e,
      );

      expect(decision, NavigationDecision.prevent);
      expect(code, isNull);
      expect(error, contains('access_denied'));
      expect(error, contains('User denied'));
    });

    test('a non-loopback URL navigates normally', () {
      final decision = chatGptNavigationDecision(
        'https://auth.openai.com/log-in',
        expectedState: _expectedState,
      );

      expect(decision, NavigationDecision.navigate);
    });

    test('a loopback URL on another path navigates normally', () {
      final decision = chatGptNavigationDecision(
        'http://localhost:1455/other',
        expectedState: _expectedState,
      );

      expect(decision, NavigationDecision.navigate);
    });

    test('a partial callback (no code, no error) navigates normally', () {
      var armed = false;
      final decision = chatGptNavigationDecision(
        'http://localhost:1455/auth/callback?state=$_expectedState',
        expectedState: _expectedState,
        onCode: (_) => armed = true,
      );

      expect(decision, NavigationDecision.navigate);
      expect(armed, isFalse);
    });

    test('an unparseable URL navigates (never crashes the delegate)', () {
      final decision = chatGptNavigationDecision(
        'http://%', // percent-encoding garbage: Uri.tryParse fails
        expectedState: _expectedState,
