        authorizeUrl: _authorizeUrl,
        expectedState: 'st-1',
      ),
      size: goldenSizePhone,
      wrap: (child) => child,
      settle: false,
    );
    blocking.onPageFinished?.call('https://accounts.google.com/o/oauth2/auth');
    await tester.pump();

    await expectGolden(tester, 'chatgpt_oauth_webview_google_block');
  });
}

