The full diff is available in the checked-out PR branch. Use `git diff` or CodeGraph for focused source navigation instead of relying only on this file.

```diff
diff --git a/flutter_app/lib/services/chatgpt_oauth_flow.dart b/flutter_app/lib/services/chatgpt_oauth_flow.dart
index fb13ffb9..13eb4029 100644
--- a/flutter_app/lib/services/chatgpt_oauth_flow.dart
+++ b/flutter_app/lib/services/chatgpt_oauth_flow.dart
@@ -15,6 +15,7 @@ import 'package:fa/services/keychain_store.dart';
 import 'package:fa/services/last_connection.dart';
 import 'package:fa/services/provider_registry.dart';
 import 'package:fa/services/session_keys_store.dart';
+import 'package:fa/ui/screens/chatgpt_oauth_webview.dart';

 /// Runs the full ChatGPT OAuth flow:
 ///
@@ -23,14 +24,19 @@ import 'package:fa/services/session_keys_store.dart';
 /// ChatGPT account, and the redirect to `http://127.0.0.1:<port>/auth/callback`
 /// is caught by the server. This mirrors the CLI flow.
 ///
-/// **iOS** — a local server is not viable. The flow shows an honest "not yet
-/// available" message until a proper in-app WebView flow is built.
+/// **iOS** — no server is ever bound. The flow assembles the PKCE authorize
+/// URL from the harness functions (`buildChatGptAuthorizeUrl`, loopback-shaped
+/// redirect) and pushes [ChatGptOAuthWebViewPage], whose `NavigationDelegate`
+/// intercepts the `http://localhost:<port>/auth/callback` redirect and hands
+/// back the state-validated `code`; the flow then completes the
+/// `exchangeChatGptAuthorizationCode` token exchange in Dart. This mirrors
+/// the CodeMie SSO WebView hop.
 ///
-/// After OAuth completes, the credentials are saved as a custom provider with
