        description: 'net::ERR_CONNECTION_REFUSED',
        isForMainFrame: true,
      ),
    );
    await tester.pump();

    await expectGolden(tester, 'chatgpt_oauth_webview_error');
  });

  testWidgets('Google sign-in block state — the E3 named message', (
