+    pageText.contains('may not be secure') ||
+        pageText.contains('disallowed_useragent')
+    ? 'Google blocks sign-in inside the in-app browser. Sign in with your '
+          'ChatGPT email and password instead, or use the desktop app for '
+          'Google sign-in.'
+    : null;
+
