    }
  }

  /// The token never decodes: surface the error and re-arm the flow (the
  /// user may retry through the SSO host).
  Future<void> _failDecode(Object e) async {
    if (mounted) {
      setState(() => _errorMessage = 'Failed to decode SSO token: $e');
      _completed = false;
    }
  }

  void _onTimeout() {
    if (!_completed && mounted) {
      _completed = true;
      Navigator.of(context).pop(null);
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Scaffold(
      appBar: faAppBar(
        title: const Text(
          'CodeMie Sign In',
        ), // l10n:ignore — proper noun, fallback-only screen
        actions: [
          if (_loading)
            const Padding(
              padding: EdgeInsets.all(14),
              child: SizedBox(
                width: 18,
                height: 18,
                child: CircularProgressIndicator(strokeWidth: 2),
              ),
            ),
        ],
      ),
      body: Stack(
        children: [
          WebViewWidget(controller: _controller),
          if (_errorMessage.isNotEmpty)
            Positioned(
              left: 16,
              right: 16,
              bottom: 16,
              child: Material(
                elevation: 4,
                borderRadius: BorderRadius.circular(12),
                color: theme.colorScheme.errorContainer,
                child: Padding(
                  padding: const EdgeInsets.all(16),
                  child: Text(
                    _errorMessage,
                    style: TextStyle(color: theme.colorScheme.onErrorContainer),
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }
}

